from pathlib import Path
import collections,datetime,hashlib,json
root=Path(__file__).resolve().parent;closed=root/'closed-inventory-r2'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
trace=closed/'session/out/oracle/inventory.jsonl';raw=trace.read_bytes();assert raw.endswith(b'\n')
rows=[json.loads(line) for line in raw.splitlines()];counts=collections.Counter(r['event'] for r in rows)
footer=rows[-1];assert footer['event']=='inventory_end' and footer['success'] is True and footer['error'] is None
assert counts['inventory_end']==1 and counts['transform']==footer['transforms']==226 and counts['component']==footer['components']==498
selection=next(r for r in rows if r['event']=='selection');assert selection['exact_matches']==1 and selection['robot_id']=='g1' and not selection['original_TryGetById_invoked'] and not selection['original_TryGetById_semantics_validated']
physics=collections.Counter(r['type'] for r in rows if r['event']=='component' and r['type'].startswith('Mujoco.'))
assert dict(physics)=={'Mujoco.MjBody':30,'Mujoco.MjInertial':30,'Mujoco.MjHingeJoint':29,'Mujoco.MjGeom':37,'Mujoco.MjFreeJoint':1,'Mujoco.MjActuator':29}
serialized=[r['serialized'] for r in rows if r.get('serialized') is not None]
assert len(serialized)==footer['completed_wrapper_calls']['JsonUtility.ToJson']==201
assert sum(v['utf8_bytes'] for v in serialized)==footer['serialized_bytes']==141465
state=json.loads((closed/'isolation/container-finished-receipt.json').read_text())
assert state['state']['Status']=='exited' and not state['state']['Running'] and state['state']['ExitCode']==0 and not state['state']['OOMKilled']
header=rows[0];assert header['plugin_sha256']=='bc8df76dbc4664a539fd80c2bb6634c3f03f8ac0bf1bda19f6c550cb5014cb35' and header['fixture_sha256']=='9acff8b3ae8e98221bf76380b232f5c92894b98b7815dab0e031d2e4e146fa07'
settings=[r for r in rows if r['event']=='loaded_global_settings'];configs=[r for r in rows if r['event']=='loaded_robot_config']
summary={'schema':'rek.original_model_inventory.result.v1','utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'complete_passive_serialized_inventory','revision':'r2','runtime_attempts_this_revision':1,'further_runs':False,'source_package_manifest_sha256':sha(root/'package/MANIFEST.json'),'closed_source_manifest_sha256':sha(closed/'SOURCE-MANIFEST.json'),'trace':{'path':'closed-inventory-r2/session/out/oracle/inventory.jsonl','bytes':len(raw),'sha256':sha(trace),'complete_json_rows':len(rows),'events':dict(counts),'success_footer_present':True},'container':state,'selection':selection,'footer':footer,'physical_component_counts':dict(physics),'loaded_counts':[r for r in rows if r['event']=='loaded_counts'],'loaded_global_settings':settings,'loaded_robot_config_names':[r['name'] for r in configs],'loaded_clip_config_names':[r['name'] for r in rows if r['event']=='loaded_clip_config'],'coverage_validation':{'footer_counts_match_records':True,'serialized_record_count_and_byte_sum_match_footer':True,'expected_prefab_hierarchy_counts_match_static_inventory':True,'original_TryGetById_was_not_invoked':True},'prior_failure':{'path':'../rek-original-model-r1/RESULT.json','trace_sha256':'53f8998ab21c131ace726f3f8f9f693a95aca9bf16b5c8f6500a475df4f7a33c','independent_ABI_review_path':'package/review/closed-inventory-independent-review-r1.json','independent_ABI_review_sha256':'d4749a58bd073c46af70c6c57becc1d4249d737dc77fe4b7e7f26bd8bc45a8f7'},'limits':['serialized fields only; transient or unsupported values unknown','No original TryGetById semantic success claim','Serialized64bit references and32bit GetInstanceID outputs remain distinct and uncorrelated','Arena global settings were loaded by ordinary isolated game startup; effective compiled mjModel options were not measured','No robot instantiation, model creation, reset, initialization, dynamics or scene load by harness; whole-process physics not instrumented','Prefab runner ONNX/config serialized references zero before initialization; no inference of absent shipped weights','No authoritative server model or current full trajectory parity claim']}
(root/'RESULT.json').write_text(json.dumps(summary,indent=2)+'\n')
(root/'RESULT.md').write_text('''# Original model inventory revision 2\n\nThe one authorized r2 passive run completed successfully: container exit 0, no OOM, and inventory_end.success=true. All 773 JSON records are complete. Closed source/readback verification covers 23 files and 687,997 bytes.\n\nThe exact original catalog was loaded and G1 selected by unique observed id through direct catalog enumeration. The unsafe generated TryGetById invocation is absent; its original semantics were not validated. The immutable first failed run and its independent ABI review are linked in RESULT.json and preserved in the source package.\n\nThe prefab inventory contains 226 transforms and 498 components, including all 30 MuJoCo bodies, 30 inertials, 29 hinge joints, one free joint, 37 geoms and 29 actuators identified by the independent static asset audit. It includes original Transform TRS, masses/inertias, hinge limits/armature/damping/friction, geom shape/contact fields, actuator fields, and serialized controller fields. It also captured two RobotConfig assets and 36 MocapClipConfig assets. The 201 JsonUtility records total 141,465 serialized bytes and agree with the footer.\n\nOne loaded MJSettings component belongs to the Arena scene. Its serialized options include integrator3, cone1, Jacobian2, solver2, iterations100 and tolerance approximately1e-8. These are actual serialized observations, not effective compiled mjModel options. The application loaded that scene during its normal isolated startup; the harness made no scene-load call.\n\nBefore and after inspection, no Robot, SonicPolicyRunner or SonicMotionComposer scene instance was found. Their asset counts increased as expected after Resources.Load. One active MjScene was already present at the first count. Whole-process physics activity was not instrumented.\n\nThis completes the serialized dependency inventory, not initialization/model parity. ONNX/config fields on the uninitialized runner prefab are zero; that does not imply missing shipped weights. References serialized as64-bit identifiers are not silently equated with32-bit GetInstanceID outputs. The next model export must establish original runtime wiring, generated model, effective options and initial mjData/controller history. No model creation, robot spawn, dynamics or further runtime was performed in this pass.\n''',encoding='utf-8')
assert len(rows)==773
print(json.dumps({'trace_sha256':sha(trace),'records':len(rows),'physical':dict(physics),'result_sha256':sha(root/'RESULT.json')},indent=2))
